import requests

from hran_pacman.bases.logger import LOGGER
from hran_pacman.bases.wft_base import WFTDownloader
from hran_pacman.exceptions import PackageComponentNotFound

sem_urls = [
    "https://sem-cache.es-ka-s3-dhn-14.eecloud.nsn-net.net/{installer}",
    "http://btssm.s3-emean-1.eecloud.nsn-net.net" + "/wcdma/installer/tags/{baseline}/{installer}",
    "http://sem-cache.s3-emean-1.eecloud.nsn-net.net/{installer}",
]


class WCDMAPackageDownloader(WFTDownloader):
    technology = "WCDMA"

    @property
    def package_name(self):
        return self.downloadable_name

    @property
    def downloadable_name(self):
        return "{}.zip".format(self.baseline)

    def get_site_manager(self):
        """
        Method downloads BTS Site Manager to current working directory
        """
        response = requests.get(self.sem_url_base.format(version=self.site_manager_baseline), stream=True)
        name = self.site_manager_baseline + ".zip"
        self._stream_to_file(name, response)


class SWBTPackageDownloader(WCDMAPackageDownloader):
    @property
    def site_manager_installer_name(self):
        baseline = self.site_manager_baseline.split("_")
        release = baseline[0]
        version = baseline[2:]
        return "BTSSiteEM-{release}-{version}_x64.bin".format(release=release, version="_".join(version))

    def get_site_manager(self):
        """
        Method downloads BTS Site Manager to current working directory
        """
        for url in sem_urls:
            sem_url = url.format(baseline=self.site_manager_baseline, installer=self.site_manager_installer_name)
            response = requests.get(sem_url, stream=True)
            if response.status_code not in range(200, 300):
                LOGGER.warning("Could not download SEM " + "from {} [HTTP {}]".format(sem_url, response.status_code))
            else:
                LOGGER.info("Downloading SEM from {}".format(sem_url))
                self._stream_to_file(self.site_manager_installer_name, response)
                return
        LOGGER.error("Could not find SEM in any of specified sources")
        raise PackageComponentNotFound("SEM package is not found")
